import{mountShell}from'../shared/shell.js?v=0.7.0';import{downloadText,readStore,writeStore}from'../shared/utils.js?v=0.7.0';import{WEEKS,PEOPLE,SKILLS,INITIAL_SKILLS,DEFAULT_TRAINING,DEFAULT_ABSENCE,SCENARIOS,normalizeSkills,normalizeTraining,simulate}from'./engine.js?v=0.7.0';
mountShell({active:'knowledge'});const $=s=>document.querySelector(s),clone=x=>structuredClone(x),KEY='thinking-lab:knowledge:v1';const initial=()=>({skills:clone(INITIAL_SKILLS),training:clone(DEFAULT_TRAINING),focus:[-1,-1,-1,-1],absence:clone(DEFAULT_ABSENCE),scenario:'battery',week:12,baseline:null});let s=readStore(KEY,initial()),past=[],result,base;try{s.skills=normalizeSkills(s.skills);s.training=normalizeTraining(s.training);if(!SCENARIOS[s.scenario]||!Array.isArray(s.focus)||s.focus.length!==4||!Number.isFinite(s.week))throw Error();s.week=Math.min(24,Math.max(1,Math.round(s.week)));simulate(s);if(s.baseline)simulate({...s,...s.baseline});}catch{s=initial();}
const n=(v,d=1)=>Number(v).toFixed(d);function compute(){result=simulate(s);base=s.baseline?simulate({...s,...s.baseline,absence:s.absence,scenario:s.scenario}):null;}function save(){if(!writeStore(KEY,s))$('#status').textContent='Saving unavailable. Export this plan.';}function change(fn,msg){past.push(clone(s));past=past.slice(-35);fn();s.training=normalizeTraining(s.training);compute();render();save();$('#status').textContent=msg||'Both plans replayed with the same workload and absence.';}
function chart(){const rows=result.history,b=base?.history,W=560,H=215,max=Math.max(1,...rows.map(r=>r.totalBacklog),...(b||[]).map(r=>r.totalBacklog)),x=i=>30+i/23*510,y=v=>180-v/max*155,path=arr=>arr.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r.totalBacklog)}`).join(' ');$('#chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" aria-hidden="true"><line x1="30" y1="180" x2="540" y2="180" stroke="var(--line)"/><text x="2" y="29">${n(max,0)}</text><text x="2" y="185">0</text>${b?`<path d="${path(b)}" fill="none" stroke="var(--line-strong)" stroke-width="2" stroke-dasharray="5 4"/>`:''}<path d="${path(rows)}" fill="none" stroke="var(--accent)" stroke-width="3"/><line x1="${x(s.week-1)}" y1="20" x2="${x(s.week-1)}" y2="180" stroke="var(--warn)"/><text x="30" y="207">W1</text><text x="510" y="207">W24</text></svg>`;$('#chart').setAttribute('aria-label',`Waiting work after 24 weeks: ${n(result.final.totalBacklog)}${base?`; baseline ${n(base.final.totalBacklog)}`:''}.`);}
function render(){const row=result.history[s.week-1];$('#skills').innerHTML=PEOPLE.map((p,i)=>`<tr><th scope="row">${p}${!row.present[i]?'<small> away</small>':''}</th>${SKILLS.map((skill,j)=>`<td><button class="skill-cell" data-person="${i}" data-skill="${j}" aria-label="${p}, ${skill.name}, starting ${n(s.skills[i][j]*100,0)} percent. Activate to cycle by 25 percent." style="--level:${s.skills[i][j]*100}%"><strong>${n(s.skills[i][j]*100,0)}%</strong><span>→ ${n(row.levels[i][j]*100,0)}%</span></button></td>`).join('')}<td><select data-focus="${i}" aria-label="Work assignment for ${p}"><option value="-1" ${s.focus[i]===-1?'selected':''}>Any work</option>${SKILLS.map((sk,j)=>`<option value="${j}" ${s.focus[i]===j?'selected':''}>${sk.name}</option>`).join('')}</select></td></tr>`).join('');$('#scenario').value=s.scenario;for(const id of['mentor','learner']){$('#'+id).innerHTML=PEOPLE.map((p,i)=>`<option value="${i}">${p}</option>`).join('');$('#'+id).value=s.training[id];}$('#skill').innerHTML=SKILLS.map((sk,i)=>`<option value="${i}">${sk.name}</option>`).join('');for(const id of['skill','start','duration'])$('#'+id).value=s.training[id];$('#enabled').checked=s.training.enabled;$('#start').max=25-s.training.duration;$('#absent').innerHTML='<option value="-1">No one away</option>'+PEOPLE.map((p,i)=>`<option value="${i}">${p}</option>`).join('');$('#absent').value=s.absence.person;$('#absence-week').value=s.absence.from;$('#grid-week').textContent=s.week;$('#week').value=s.week;$('#week-label').value=s.week;$('#undo').disabled=!past.length;$('#pin').textContent=s.baseline?'Replace baseline':'Pin baseline';$('#training-block').style.left=(s.training.start-1)/24*100+'%';$('#training-block').style.width=s.training.duration/24*100+'%';$('#training-block').classList.toggle('off',!s.training.enabled);$('#training-label').textContent=`${s.training.duration} weeks · ${PEOPLE[s.training.mentor]} → ${PEOPLE[s.training.learner]}`;$('#absence-marker').style.left=(s.absence.from-1)/24*100+'%';$('#absence-marker').hidden=s.absence.person<0||s.absence.from>24;$('#delivered').textContent=n(result.final.delivered);$('#backlog').textContent=n(result.final.totalBacklog);$('#coaching').textContent=n(result.final.learningTime);$('#coverage').textContent=result.final.levels.filter((levels,p)=>result.final.present[p]&&levels[1]>=.6).length;$('#delta').textContent=base?`${n(result.final.delivered-base.final.delivered)} vs baseline`:'Pin a baseline to compare';$('#comparison').textContent=base?'Solid line: current plan. Dashed: baseline. Same demand, absence and initial knowledge unless you deliberately change the starting skill grid.':'Solid line: current backlog. Pin a plan before changing the intervention.';$('#week-detail').innerHTML=`<p>${row.coaching?`Coaching uses ${n(2*s.training.fraction)} person-weeks; ${PEOPLE[s.training.learner]} gains ${n(row.coachingGain*100)} skill points at week end.`:row.blockedCoaching?'Scheduled coaching cannot happen because a participant is absent or mentor equals learner.':'No coaching this week.'}</p><div class="week-bars">${SKILLS.map((sk,j)=>`<p><strong>${sk.name}</strong>: ${n(row.output[j])} output · ${n(row.backlog[j])} waiting</p>`).join('')}</div><p>Work plus coaching and idle time cannot exceed each present person’s week. Learning appears after the work that produced it.</p>`;chart();}
$('#skills').addEventListener('click',e=>{const b=e.target.closest('[data-person]');if(b){const p=+b.dataset.person,j=+b.dataset.skill;change(()=>s.skills[p][j]=s.skills[p][j]>=1?0:Math.min(1,Math.round((s.skills[p][j]+.25)*100)/100),'Starting skill assumption changed; this is not free training.');}});$('#skills').addEventListener('change',e=>{if(e.target.dataset.focus!==undefined){const p=+e.target.dataset.focus,v=+e.target.value;change(()=>s.focus[p]=v);}});for(const id of['mentor','learner','skill','start','duration'])$('#'+id).addEventListener('change',e=>{const v=+e.target.value;change(()=>s.training[id]=v);});$('#enabled').onchange=e=>{const v=e.target.checked;change(()=>s.training.enabled=v);};$('#scenario').onchange=e=>{const v=e.target.value;change(()=>s.scenario=v);};for(const id of['absent','absence-week'])$('#'+id).onchange=e=>{const v=+e.target.value;change(()=>s.absence[id==='absent'?'person':'from']=v);};$('#week').oninput=e=>{s.week=+e.target.value;render();};$('#week').onchange=save;$('#pin').onclick=()=>change(()=>s.baseline={skills:clone(s.skills),training:clone(s.training),focus:clone(s.focus)},'Current plan pinned. Absence and demand stay shared.');$('#undo').onclick=()=>{if(past.length){s=past.pop();compute();render();save();}};$('#reset').onclick=()=>change(()=>{const baseline=s.baseline;s=initial();s.baseline=baseline;},'Default plan restored; baseline kept.');
const block=$('#training-block');let drag=null;block.style.touchAction='none';block.onpointerdown=e=>{if(e.button!==0)return;drag={x:e.clientX,start:s.training.start,before:clone(s),width:$('#training-track').clientWidth};block.setPointerCapture(e.pointerId);};block.onpointermove=e=>{if(!drag)return;s.training.start=Math.max(1,Math.min(25-s.training.duration,drag.start+Math.round((e.clientX-drag.x)/drag.width*24)));compute();render();};block.onpointerup=e=>{if(!drag)return;if(s.training.start!==drag.start)past.push(drag.before);drag=null;render();save();block.releasePointerCapture(e.pointerId);};block.onpointercancel=()=>{if(drag){s=drag.before;drag=null;compute();render();}};block.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();change(()=>s.training.start+=e.key==='ArrowRight'?1:-1);block.focus();}};$('#export').onclick=()=>downloadText('knowledge-plan.md',`# Specialists and shared knowledge\n\nSituation: ${SCENARIOS[s.scenario].name}. ${n(result.final.delivered)} completed, ${n(result.final.totalBacklog)} waiting after 24 weeks. Coaching costs ${n(result.final.learningTime)} person-weeks.\n\n${base?`Baseline completed ${n(base.final.delivered)} on the same demand and absence.\n\n`:''}Fictional divisible-work mechanism; no certification or staffing forecast.\n\n\`\`\`json\n${JSON.stringify({plan:s,weekly:result.history},null,2)}\n\`\`\`\n`,'text/markdown');compute();render();
